function partitionGrid(layout,ox,oy,scale){const rows=layout?layout.split('/'):['AAAA','AAAA','AAAA','AAAA'];let out='';for(let y=0;y<4;y++)for(let x=0;x<4;x++){const name=rows[y][x],fill=layout?({A:'#fff',B:'#ddd',C:'#aaa',D:'#888'}[name]):'#fff';out+=`<rect x="${ox+x*scale}" y="${oy+y*scale}" width="${scale}" height="${scale}" fill="${fill}" stroke="#aaa" stroke-width=".7"/>`;if(y===0||rows[y-1][x]!==name)out+=`<path d="M${ox+x*scale} ${oy+y*scale} h${scale}" stroke="#191511" stroke-width="2"/>`;if(x===0||rows[y][x-1]!==name)out+=`<path d="M${ox+x*scale} ${oy+y*scale} v${scale}" stroke="#191511" stroke-width="2"/>`;if(y===3)out+=`<path d="M${ox+x*scale} ${oy+4*scale} h${scale}" stroke="#191511" stroke-width="2"/>`;if(x===3)out+=`<path d="M${ox+4*scale} ${oy+y*scale} v${scale}" stroke="#191511" stroke-width="2"/>`;}return out;}
