function compassOrder85(){const base='<path d="M20 82 H170"/><text x="10" y="97">ㄴ</text><text x="180" y="97">ㄷ</text><text x="95" y="100">5cm</text>';const first='<path d="M118.3 13.17 A120 120 0 0 1 138.18 61.16" stroke-dasharray="4 3"/>';const second='<path d="M120.85 47.59 A60 60 0 0 1 152.64 24.62" stroke-dasharray="4 3"/>';const pen1='<path d="M20 82 L40 8 L131 36.4"/><circle cx="40" cy="8" r="3" fill="white"/>';const pen2='<path d="M170 82 L160 6 L131 36.4"/><circle cx="160" cy="6" r="3" fill="white"/>';const triangle='<path d="M20 82 L131 36.4 L170 82"/><text x="130" y="29">ㄱ</text><text x="64" y="43">4cm</text><text x="158" y="51">2cm</text>';const panel=(x,y,label,extra)=>`<g transform="translate(${x} ${y})"><text x="5" y="14" font-size="17">${label}</text>${base}${extra}</g>`;return `<svg class="u3p89-figure" style="max-width:430px" viewBox="0 0 430 335" role="img" aria-label="변 ㄴㄷ 5cm, ㄴㄱ 4cm, ㄷㄱ 2cm인 삼각형과 작도 그림 네 개: ㄱ은 두 원호가 만나는 단계, ㄴ은 선분만 그린 단계, ㄷ은 완성된 삼각형, ㄹ은 첫 원호를 그리는 단계"><g fill="none" stroke="#191511" stroke-width="1.5"><g font-size="13" fill="#191511" stroke="none"><g transform="translate(110 0)">${base}${triangle}</g>${panel(0,115,'ㄱ',first+second+pen2)}${panel(220,115,'ㄴ','')}${panel(0,225,'ㄷ',triangle)}${panel(220,225,'ㄹ',first+pen1)}</g></g></svg>`.replaceAll('<path d=', '<path stroke="#191511" fill="none" d=').replaceAll('<circle cx=', '<circle stroke="#191511" cx=');}
